        type: "ifc-demo",
        modelId: "duplex-architecture",
        title: "Inspecter les Pset visuellement",
        description: "Ouvrez le duplex et cliquez sur n'importe quel élément pour voir l'ensemble de ses jeux de propriétés — les mêmes données que renvoie get_psets(), sans écrire une ligne de code.",
