        text: "Le RGPD n'est pas seulement un problème pour le service informatique. Il s'applique à toute équipe qui traite des informations sur des personnes identifiables — et sur un projet de construction, cela peut concerner les coordinateurs BIM, les chefs de projet et les équipes de livraison.",
