        type: "p",
        text: "Quand vous utilisez un outil BIM cloud qui traite les fichiers IFC sur ses serveurs, deux rôles RGPD sont créés. Vous (ou votre organisation) êtes le responsable du traitement — vous déterminez la finalité du traitement. L'éditeur de l'outil est sous-traitant — il agit pour votre compte. L'article 28 du RGPD exige un accord écrit de traitement des données (DPA) entre vous et chaque sous-traitant avant de partager des données personnelles avec lui.",
