        text: "Les trois niveaux forment un point de contrôle qualité que traverse une maquette, dans l'ordre. Chaque niveau a une cadence différente : le niveau 1 s'exécute à chaque export (un contrôle de bon sens), le niveau 2 avant tout téléversement en CDE (le point de contrôle qualité), le niveau 3 avant les jalons de livraison formels (le contrôle contractuel). Les exécuter dans le désordre fait perdre du temps — il n'y a aucun intérêt à exécuter un contrôle IDS sur un fichier dont la hiérarchie spatiale est rompue.",
