        text: "Une précision technique importante : lorsque vous envoyez un fichier IFC vers Autodesk Viewer, celui-ci est converti du format IFC vers le format interne SVF2 d'Autodesk. Cette conversion peut faire perdre des données sémantiques IFC — structures des jeux de propriétés, références de classification et certaines relations géométriques — d'une manière invisible dans le rendu affiché. Autodesk Viewer ne doit pas être utilisé pour vérifier la correction structurelle des données IFC ; il doit servir uniquement à la revue visuelle.",
