        text: "Idéal pour : les équipes multidisciplinaires qui ont besoin d'un espace de coordination partagé avec gestion des problèmes BCF, et qui n'exigent pas de traitement des données sur l'appareil. Offre gratuite disponible ; forfaits payants pour des volumes de projets plus importants.",
