        type: "p",
        text: "Le buildingSMART Validation Service n'est pas une visionneuse IFC : il n'a pas de moteur de rendu de géométrie. C'est l'outil de référence officiel pour le contrôle de conformité au schéma IFC, développé et maintenu par buildingSMART International. Il valide les fichiers IFC envoyés par rapport aux règles du schéma EXPRESS, aux propositions informelles et aux accords d'implémentation normatifs pour IFC 2x3 et IFC 4. Il valide aussi les fichiers de schéma IDS — c'est-à-dire la structure XML du .ids elle-même, sans exécuter une spécification IDS sur le contenu d'une maquette.",
