        type: "p",
        text: "Son public principal est celui des développeurs de logiciels de modélisation IFC qui doivent certifier que leur outil exporte de l'IFC valide. Pour les coordinateurs BIM qui contrôlent la qualité d'une maquette, ce n'est pas le bon outil : il vous dira si le fichier IFC est syntaxiquement correct, mais pas si les données sont pertinentes, complètes ou conformes aux exigences du projet. Utilisez-le pour certifier qu'un export d'outil respecte les normes de schéma de buildingSMART. Ne l'utilisez pas comme substitut au contrôle qualité d'une maquette.",
