        text: "Solibri est la référence du secteur pour un contrôle qualité BIM sérieux. C'est une application de bureau pour Windows et Mac. La version commerciale est utilisée par de grands bureaux d'ingénierie et de construction pour le contrôle de maquette par règles, l'audit de conformité et la coordination. Solibri Anywhere est une version gratuite et complète disponible pour un usage non commercial — étudiants, universitaires et particuliers qui apprennent l'outil peuvent l'utiliser sans frais.",
